import { describe, expect, it } from 'vitest';
import { aiSummary } from './aisummary';

// The demo's analysis (generated by playground/generate.sh; git-ignored, so it may be absent).
const generated = Object.values(import.meta.glob('../../playground/analysis.json', { query: '?raw', import: 'default', eager: true })) as string[];

describe('aiSummary', () => {
  it('keeps aggregates and drops transactions, wording, accounts and days', () => {
    if (!generated.length) return;
    const a = JSON.parse(generated[0]);
    const s = aiSummary(a, 'My project');
    const text = JSON.stringify(s);
    expect(s.kind).toBe('wdmg-ai-summary');
    expect((s.spend_by_category as unknown[]).length).toBe(a.spend_by_category.length);
    expect(text).not.toMatch(/\b\d{4}-\d{2}-\d{2}\b/); // months only
    expect(text).not.toContain('"transactions"');
    expect(text).not.toContain('matched_pairs');
    for (const acct of a.by_account) expect(text).not.toContain(`"${acct.id}"`);
    for (const p of a.by_person) expect(text).not.toContain(`"${p.id}"`);
    expect(text).not.toContain('My project');
    const raw = a.transactions.find((t: { raw_description?: string; merchant: string }) => t.raw_description && t.raw_description !== t.merchant);
    if (raw) expect(text).not.toContain(raw.raw_description);
  });
  it('strips days and names from a small example', () => {
    const s = aiSummary({
      period: { start: '2999-01-03', end: '2999-02-27' },
      by_person: [{ id: 'leela', spend: '1', income: '2', net: '1' }],
      by_account: [{ id: 'Leela Savings', spend: '1', income: '2', net: '1' }],
      anomalies: [{ method: 'rare_large', merchant: 'SLURM', period_or_date: '2999-02-14', reason: 'Big SLURM run on 2999-02-14', amount: '90' }],
      transactions: [{ date: '2999-02-14', merchant: 'SLURM', raw_description: 'SLURM #42 NNY', account: 'Leela Savings' }],
    });
    const text = JSON.stringify(s);
    expect(text).not.toMatch(/2999-0\d-\d\d/);
    expect(text).not.toMatch(/leela|Leela Savings|#42/i);
    expect(text).toContain('Person 1');
    expect(text).toContain('SLURM');
  });
  it('works on an empty analysis', () => {
    expect(aiSummary({}).monthly).toEqual([]);
  });
});
